REVIEW_ESSAY = [
dict(qid="U1-ESS-01", lesson="1-1", text="اشرح تطور تقنية المعلومات في الفترة الممتدة من الأربعينيات إلى الستينيات موضحا استخدامها الأساسي في تلك الفترة؟", answer="ظهرت الحواسيب الإلكترونية الأولى في الأربعينيات وكانت ضخمة ومحدودة الاستخدام. في الخمسينيات والستينيات استخدمت أساسا في الحسابات العلمية والعسكرية والإدارية الكبيرة لدى الحكومات والشركات. لم تكن للاستخدام الشخصي بل لمعالجة البيانات المركزية.", evidence="جدول مراحل تطور تقنية المعلومات في الدرس.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-02", lesson="1-1", text="وضح المقصود بقانون مور وهل يعد قانونا فيزيائيا ثابتا؟ فسر إجابتك.", answer="قانون مور ملاحظة تجريبية بأن عدد الترانزستورات في الدوائر المتكاملة يتضاعف تقريبا كل عامين. هو ليس قانونا فيزيائيا ثابتا بل اتجاه تاريخي في صناعة الرقائق. لذلك يواجه حدودا هندسية وفيزيائية مع استمرار التصغير.", evidence="نص الدرس عن قانون مور.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-03", lesson="1-2", text="اذكر ثلاثة تغيرات اجتماعية ناتجة عن تقنية المعلومات؟", answer="من التغيرات: شبكات التواصل الاجتماعي، والتجارة الإلكترونية، والعمل عن بعد، والتعلم عبر الإنترنت، والدفع غير النقدي. يختار الطالب ثلاثة منها مع تعريف موجز لكل واحد. كلها نتجت عن انتشار الإنترنت والحوسبة.", evidence="قائمة التحولات المجتمعية الخمسة في الدرس.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-04", lesson="1-2", text="ما المقصود بمصطلح التجارة الإلكترونية (E-commerce)؟ موضحا ذلك بمثالين.", answer="التجارة الإلكترونية هي بيع السلع والخدمات وشراؤها عبر الإنترنت. مثالاها: الشراء من متجر إلكتروني مثل أمازون، وطلب الطعام أو حجز الخدمات عبر التطبيقات. وقد وسعت الوصول إلى الأسواق وقللت الاعتماد على المتاجر التقليدية.", evidence="تعريف التجارة الإلكترونية ضمن التحولات الخمسة.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-05", lesson="1-2", text="وضح كيف تساهم الحوسبة الطرفية في تعزيز الأمان وسرعة اتخاذ القرار في تقنية القيادة الذاتية دون الحاجة لإرسال البيانات إلى السحابة؟", answer="الحوسبة الطرفية تعالج البيانات على الجهاز نفسه فورا بدل إرسالها إلى السحابة. في القيادة الذاتية تحلل الكاميرات والمستشعرات المحيط وتتخذ القرار لحظيا مما يقلل التأخير. كما يقلل إرسال البيانات الحساسة فيعزز الأمان والخصوصية.", evidence="فقرة القيادة الذاتية والحوسبة الطرفية.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-06", lesson="1-2", text="قارن بإيجاز بين الواقع المعزز (AR) والواقع الافتراضي (VR) من حيث التعريف وطريقة العمل؟", answer="الواقع المعزز يضيف عناصر أو معلومات رقمية إلى مشهد من العالم الحقيقي. أما الواقع الافتراضي فيضع المستخدم داخل بيئة افتراضية مولدة حاسوبيا بالكامل تحجب الواقع. الأول يعزز الواقع والثاني يستبدله.", evidence="تعريفا الواقع المعزز والواقع الافتراضي في التقنيات الناشئة.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-07", lesson="1-2", text="اشرح المبدأ الذي يقوم عليه الكيوبت (qubit) في الحوسبة الكمومية وكيف يختلف عن البت الكلاسيكي؟", answer="البت الكلاسيكي يحمل حالة واحدة إما 0 أو 1 في كل وقت. أما الكيوبت فيستخدم مبدأ التراكب الكمي فيكون مزيجا من 0 و1 في نفس الوقت. هذا يمنح الحوسبة الكمومية قدرة معالجة مختلفة لمعلومات معقدة.", evidence="فقرة الحوسبة الكمومية والتراكب.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-08", lesson="1-2", text="كيف غير انتشار الحوسبة السحابية من العقد الثاني من الألفية فصاعدا طريقة تقديم موارد تقنية المعلومات؟", answer="أصبحت موارد تقنية المعلومات تقدم كخدمة عبر الإنترنت بدلا من امتلاك أجهزة محلية. مكن ذلك تخزين البيانات وتحليل البيانات الضخمة ودعم تطبيقات الذكاء الاصطناعي. فقلت التكلفة وزادت المرونة وقابلية التوسع.", evidence="مرحلة العقد الثاني من الألفية في جدول التطور.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-09", lesson="1-1", text="اشرح المراحل التاريخية لتطور تقنية المعلومات منذ ظهور الحواسيب الإلكترونية في الأربعينيات وحتى الستينيات مبينا الغرض الأساسي لاستخدامها في تلك الفترة.", answer="بدأت الحواسيب الإلكترونية في الأربعينيات بحجم كبير وقدرة محدودة. خلال الخمسينيات والستينيات استخدمت أساسا للحسابات الحكومية والعلمية وإدارة بيانات المؤسسات الكبيرة. لم تكن شخصية ولا شبكية بعد.", evidence="جدول المراحل المبكرة في الدرس.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-10", lesson="1-1", text="اشرح قانون مور موضحا ما يصفه، والتحديات الهندسية والفيزيائية التي تواجه استمرار تصغير مكونات الدوائر.", answer="يصف قانون مور تضاعف عدد الترانزستورات في الدوائر المتكاملة كل عامين تقريبا. استمراره يتطلب تصغيرا دائما للمكونات. التحديات تشمل الحرارة وتسرب التيار وحدود المواد الفيزيائية ودقة التصنيع.", evidence="شرح قانون مور وحدود التصغير.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-11", lesson="1-2", text="عدد التحولات المجتمعية الخمسة الناتجة عن تقنية المعلومات موضحا مفهوم كل من العمل عن بعد والتجارة الإلكترونية.", answer="التحولات الخمسة: شبكات التواصل الاجتماعي، والتجارة الإلكترونية، والعمل عن بعد، والتعلم عبر الإنترنت، والدفع غير النقدي. العمل عن بعد هو أداء المهام من المنزل أو موقع بعيد عبر الإنترنت. والتجارة الإلكترونية هي البيع والشراء عبر الإنترنت.", evidence="قائمة التحولات الخمسة نصا في الدرس.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-12", lesson="1-2", text="وضح خصائص واستخدامات التقنيات الناشئة الثلاث البارزة المذكورة في الدرس (القيادة الذاتية، الواقع المعزز / الافتراضي، والحوسبة الكمومية).", answer="القيادة الذاتية تستخدم الذكاء الاصطناعي والكاميرات والمستشعرات والحوسبة الطرفية لإدراك المحيط واتخاذ القرار. والواقع المعزز يضيف معلومات رقمية للواقع بينما الافتراضي يبني بيئة حاسوبية كاملة. والحوسبة الكمومية تعتمد على الكيوبت والتراكب لمعالجة المعلومات.", evidence="فقرات التقنيات الناشئة الثلاث.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-13", lesson="1-3", text="عرف مفهوم الذكاء الاصطناعي موضحا في ثلاث نقاط الفرق بين التعلم الآلي والتعلم العميق والذكاء الاصطناعي التوليدي.", answer="الذكاء الاصطناعي مجال واسع لأنظمة تنفذ مهاما مثل التعلم والتنبؤ والتعرف على الكلام والصور. التعلم الآلي فرع منه تتعلم فيه النماذج الأنماط من البيانات. والتعلم العميق أسلوب من التعلم الآلي بشبكات عصبية متعددة الطبقات، والتوليدي ينشئ محتوى جديدا اعتمادا على نماذج التعلم العميق.", evidence="مخطط العلاقة بين المفاهيم الأربعة.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-14", lesson="1-3", text="اشرح كيف تتعلم النماذج في فرع التعلم الآلي مقارنة بالطرق التقليدية المعتمدة على البرمجة الصريحة للقواعد.", answer="في البرمجة التقليدية يكتب الإنسان كل قاعدة صراحة بشكل ثابت. في التعلم الآلي تتعلم النماذج الأنماط من البيانات لإجراء تنبؤات أو تصنيفات دون برمجة كل قاعدة. فتتحسن بالتدريب على الأمثلة.", evidence="المقارنة بين البرمجة الصريحة والتعلم من البيانات.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-15", lesson="1-3", text="ما المكونات الأساسية للشبكة العصبية الاصطناعية؟", answer="تتكون من طبقات متصلة تضم وحدات عصبونية مستوحاة بصورة مبسطة من ترابط العصبونات. تتغير أوزان الوصلات أثناء التدريب لتعلم الأنماط المعقدة. وبها طبقة إدخال وطبقات خفية وطبقة إخراج.", evidence="تعريف الشبكة العصبية في الدرس.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-16", lesson="1-3", text="اشرح مفهوم الذكاء الاصطناعي التوليدي (GenAI) موضحا ذلك بأمثلة.", answer="الذكاء الاصطناعي التوليدي وظيفته إنشاء محتوى جديد مثل النصوص والصور والصوت والبرمجيات. يعتمد غالبا على نماذج التعلم العميق والشبكات العصبية. من أمثلته نموذج ChatGPT لتوليد النصوص وأدوات توليد الصور والصوت.", evidence="فقرة الذكاء الاصطناعي التوليدي وأمثلته.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-17", lesson="1-3", text="اشرح العلاقة بين الذكاء الاصطناعي والتعلم الآلي والتعلم العميق والذكاء الاصطناعي التوليدي؟", answer="الذكاء الاصطناعي هو المجال الأوسع. التعلم الآلي فرع منه. التعلم العميق أسلوب من التعلم الآلي يعتمد على شبكات عصبية متعددة الطبقات. والتوليدي يعتمد غالبا على نماذج التعلم العميق لإنشاء محتوى جديد.", evidence="التسلسل الهرمي للمفاهيم في الدرس.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-18", lesson="1-3", text="وضح المقصود بمصطلح الهلوسة في سياق الذكاء الاصطناعي التوليدي؟", answer="الهلوسة هي إنتاج نص أو معلومات تبدو معقولة ومنطقية لكنها غير صحيحة واقعيا أو غير مدعومة. خطورتها أنها تبدو مقنعة للمستخدم. لذلك يجب التحقق من المخرجات من مصادر موثوقة.", evidence="فقرة الهلوسة والتحقق.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-19", lesson="1-4", text="افترض أن مزارعا يريد استخدام نظام ذكاء اصطناعي للتمييز بين صور المحاصيل السليمة والمصابة بالأمراض. اشرح نوع البيانات التي يحتاجها النظام للتدريب، وحدد عاملا قد يجعل تنبؤه خاطئا؟", answer="يحتاج النظام إلى بيانات تدريب وهي أمثلة كثيرة مصنفة من صور المحاصيل السليمة والمصابة. إذا كانت البيانات متحيزة أو غير كافية أو لا تمثل الواقع بدقة فسيخطئ التنبؤ. كذلك انعكاس تمييز سابق أو نقص سمات معينة يسبب تحيزا.", evidence="فقرتا بيانات التدريب وأسباب التحيز مع تطبيق الزراعة.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-20", lesson="1-3", text="تحدث عن فائدة واحدة ومخاطرة واحدة لاستخدام الذكاء الاصطناعي التوليدي في كتابة تقرير مدرسي. وماذا ينبغي على المتعلمين فعله للتحقق من المخرجات؟", answer="الفائدة سرعة توليد مسودة وأفكار ونصوص. والمخاطرة الهلوسة أي معلومات خاطئة تبدو مقنعة. ينبغي على المتعلمين مراجعة المخرجات والتحقق منها من مصادر موثوقة وعدم الاعتماد عليها مباشرة.", evidence="فقرة الهلوسة وضرورة التحقق.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-21", lesson="1-3", text="عرف الذكاء الاصطناعي ووضح كيف تختلف الأنظمة الذكية اليوم عن الحواسيب التقليدية المبرمجة بقواعد ثابتة؟", answer="الذكاء الاصطناعي أنظمة حاسوبية تنفذ مهاما مثل التعلم والتنبؤ والتعرف على الكلام والصور. الحواسيب التقليدية تعمل بقواعد مبرمجة يدويا بشكل صارم وثابت. أما الأنظمة الذكية فتتعلم الأنماط من البيانات وتتنبأ وتصنف.", evidence="تعريف الذكاء الاصطناعي مقابل البرمجة التقليدية.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-22", lesson="1-3", text="اشرح بالتفصيل العلاقة المتداخلة بين الذكاء الاصطناعي والتعلم الآلي والتعلم العميق مدعما إجابتك بالمفاهيم الأساسية لكل منها؟", answer="الذكاء الاصطناعي المجال الواسع للتعلم والتنبؤ والتعرف. التعلم الآلي فرع تتعلم فيه النماذج أنماطا من البيانات دون برمجة كل قاعدة. التعلم العميق أسلوب من التعلم الآلي بشبكات عصبية متعددة الطبقات لتعلم تمثيلات معقدة كالصور والكلام.", evidence="تعريفات المفاهيم الثلاثة.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-23", lesson="1-3", text="ما هو الذكاء الاصطناعي التوليدي، وكيف يعتمد على نماذج التعلم العميق لإنشاء محتوى جديد كالنصوص والصور؟", answer="التوليدي وظيفته إنشاء محتوى جديد كالنصوص والصور والصوت والبرمجيات. يعتمد غالبا على نماذج التعلم العميق والشبكات العصبية المدربة على بيانات ضخمة. فيتعلم التمثيلات ثم يولد محتوى مشابها.", evidence="فقرة اعتماد الذكاء التوليدي على التعلم العميق.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-24", lesson="1-3", text="ناقش مشكلة الهلوسة في الذكاء الاصطناعي التوليدي، موضحا سبب خطورتها والإجراء المناسب للتحقق من المخرجات؟", answer="الهلوسة توليد معلومات غير صحيحة أو غير مدعومة تبدو مقنعة. خطورتها تضليل المستخدم خاصة في التقارير والدراسة. الإجراء المناسب التحقق من المخرجات بمقارنتها بمصادر موثوقة ومراجعة بشرية.", evidence="فقرة احتياطات الاستخدام والهلوسة.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-25", lesson="1-3", text="اشرح كيف أصبحت تقنيات مثل منصات الفيديو والمساعدات الصوتية جزءا من الخدمات اليومية، وما هو الدور الأساسي للذكاء الاصطناعي فيها؟", answer="أصبحت أنظمة التوصية تقترح الفيديوهات من بيانات السلوك السابق، والمساعدات الصوتية تفهم الأوامر وتنفذها. دور الذكاء الاصطناعي التنبؤ بالتفضيلات وفهم الصوت والتعرف على الصور. فصارت جزءا يوميا مثل يوتيوب وSiri ومساعد جوجل.", evidence="فقرة الخدمات اليومية.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-26", lesson="1-3", text="وضح المقصود بالذكاء الاصطناعي للتشخيص بالصور في مجال الرعاية الصحية، وكيف يسهم في الكشف عن الأمراض؟", answer="هو استخدام الذكاء الاصطناعي لتحليل الصور الطبية مثل الأشعة السينية والتصوير المقطعي. يسهم في الكشف المبكر عن الأمراض واكتشاف الأدوية. فيساعد الأطباء ولا يغني عن الحكم البشري.", evidence="فقرة الرعاية الصحية.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-27", lesson="1-3", text="اذكر أربع خدمات أساسية للذكاء الاصطناعي في الحياة اليومية مع بيان دور الذكاء الاصطناعي في كل خدمة؟", answer="الخدمات: نظام التوصية يتنبأ بالتفضيلات من السلوك السابق، والمساعد الصوتي يتعرف على الصوت ويفهم الأوامر، والترجمة الآلية تترجم النص تلقائيا، والتعرف على الوجه يكشف الوجوه ويتعرف عليها لفتح الهاتف وتنظيم الصور. كلها تعتمد على التعلم من البيانات.", evidence="قائمة الخدمات اليومية الأربع.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-28", lesson="1-3", text="ما هو الدور الذي يلعبه الذكاء الاصطناعي في قطاع التصنيع؟ اذكر مثالين توضيحيين.", answer="في التصنيع يستخدم لفحص جودة المنتج والتنبؤ بأعطال الآلات قبل وقوعها. المثالان: كشف العيوب في خط الإنتاج، والصيانة التنبؤية لتقليل التوقف. فيرفع الكفاءة ويخفض التكلفة.", evidence="فقرة قطاع التصنيع.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-29", lesson="1-3", text="وضح كيف يتم استخدام الذكاء الاصطناعي في قطاع الزراعة ودوره في مراقبة المحاصيل والآفات.", answer="يستخدم للتنبؤ بموعد الحصاد والكشف عن الآفات والأمراض من الصور. يراقب المحاصيل عبر تحليل الصور والبيانات الحقلية. فيساعد المزارع على التدخل المبكر وزيادة الإنتاج.", evidence="فقرة قطاع الزراعة.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-30", lesson="1-3", text="اذكر أربعة مهام يمكن أن يؤديها الذكاء الاصطناعي في معالجة البيانات المعقدة والتعرف على الصور والأصوات.", answer="المهام: إيجاد وتصنيف الأنماط في البيانات المعقدة، والتعرف على الصور، والتعرف على الكلام، والتنبؤ والتصنيف والترجمة والتوصية. يبرع فيها بالاستدلال الاحتمالي من البيانات. وتظهر في الخدمات اليومية والقطاعات.", evidence="فقرة ما يبرع فيه الذكاء الاصطناعي وقائمة الخدمات.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-31", lesson="1-4", text="اشرح مقولة الذكاء الاصطناعي بارع في إيجاد الأنماط في البيانات، لكن الحكم البشري لا يزال ضروريا.", answer="يبرع الذكاء الاصطناعي في إيجاد وتصنيف الأنماط في البيانات المعقدة والاستدلال الاحتمالي. لكنه لا يتخذ الأحكام الأخلاقية المطلقة ولا يضمن خلو المخرجات من التحيز. لذلك يبقى الحكم البشري ضروريا في القرارات ذات البعد الأخلاقي والخصوصية.", evidence="فقرة قدرات الذكاء مقابل الحذر البشري.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-32", lesson="1-4", text="اذكر ثلاثة احتياطات للاستخدام المتعلقة بالذكاء الاصطناعي.", answer="الاحتياطات: الانتباه للهلوسة والتحقق من المعلومات، وإدراك مشكلة الصندوق الأسود وعدم وضوح القرار، والحذر من التحيز في بيانات التدريب وحماية الخصوصية وحقوق المؤلف. مع إبقاء المسؤولية البشرية.", evidence="قائمة احتياطات الاستخدام.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-33", lesson="1-3", text="اشرح كيفية استخدام أنظمة التوصية في الحياة اليومية مع ذكر أمثلة تطبيقية مثل يوتيوب وأمازون؟", answer="نظام التوصية يتنبأ بالتفضيلات من بيانات السلوك السابق ويعرض التوصيات. في يوتيوب يقترح الفيديوهات، وفي أمازون يقترح السلع. فيزيد التخصيص ويعتمد على التعلم الآلي.", evidence="تعريف نظام التوصية وأمثلته.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-34", lesson="1-3", text="اذكر استخدامات الذكاء الاصطناعي في الرعاية الصحية؟", answer="يستخدم للتشخيص بالصور من الأشعة السينية والتصوير المقطعي للكشف عن الأمراض. كما يستخدم في تحليل الصور الطبية واكتشاف الأدوية. فيسرع التشخيص ويدعم القرار الطبي.", evidence="فقرة الرعاية الصحية.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-35", lesson="1-3", text="اذكر أربعة قطاعات صناعية رئيسية يتم فيها إدخال تقنيات الذكاء الاصطناعي مع بيان دور كل قطاع باختصار؟", answer="الرعاية الصحية للكشف عن الأمراض من الصور، والتصنيع لفحص الجودة والصيانة التنبؤية، والزراعة للتنبؤ بالحصاد وكشف الآفات، والخدمات اللوجستية لتحسين مسارات التوصيل. كل قطاع يستفيد من تحليل البيانات والتنبؤ.", evidence="قائمة القطاعات الأربع.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-36", lesson="1-4", text="اشرح ما يبرع فيه الذكاء الاصطناعي وما يتطلب الحذر عند استخدامه فيما يتعلق بالقرارات ذات البعد الأخلاقي والخصوصية؟", answer="يبرع في إيجاد وتصنيف الأنماط في البيانات المعقدة والاستدلال الاحتمالي. ويتطلب الحذر في الأحكام الأخلاقية وحماية البيانات الشخصية وقضايا المراقبة. فلا يجوز تركه يتخذ قرارات حساسة دون إشراف بشري.", evidence="فقرة القدرات مقابل الحذر الأخلاقي.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-37", lesson="1-4", text="ما المقصود بمصطلح التحيز الخوارزمي في أنظمة الذكاء الاصطناعي، وما هي أبرز أشكاله أو أمثلته؟", answer="التحيز الخوارزمي نمط في مخرجات الذكاء الاصطناعي قد يؤدي إلى نتائج غير عادلة أو ضارة. يظهر كتمييز ضد شخص أو مجموعة بسبب بيانات متحيزة. مثاله تنبؤات غير عادلة لفئات ممثلة تمثيلا ناقصا.", evidence="تعريف التحيز الخوارزمي.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-38", lesson="1-4", text="وضح الأسباب الرئيسية لنشوء التحيز الخوارزمي في أنظمة الذكاء الاصطناعي؟", answer="الأسباب: بيانات تدريب متحيزة، وانعكاس نزعات تمييزية سابقة في البيانات، ووجود بيانات غير كافية عن سمات معينة. فنقص التمثيل يجعل النموذج يعمم خطأ. وليست سرعة المعالجة سببا له.", evidence="قائمة أسباب التحيز.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-39", lesson="1-4", text="اشرح كيف أدى تطور تقنية الذكاء الاصطناعي إلى ظهور قضايا جديدة تتعلق بالخصوصية والمراقبة في الأماكن العامة.", answer="مكن الذكاء الاصطناعي التعرف على الأفراد وتتبعهم عبر التعرف على الوجه في الصور والأماكن العامة. هذا يثير قضايا جمع البيانات الشخصية والمراقبة المستمرة. فيتطلب ضوابط للتعامل المناسب مع البيانات وحمايتها.", evidence="فقرة الخصوصية والتعرف على الوجه.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
dict(qid="U1-ESS-40", lesson="1-4", text="ما المقصود بمصطلح بيانات التدريب في أنظمة الذكاء الاصطناعي، وكيف يؤثر نقص تمثيلها على المخرجات؟", answer="بيانات التدريب هي الأمثلة التي يتعلم منها النظام أنماطه قبل استخدامه. إذا كانت غير كافية أو غير ممثلة للواقع بدقة انحرفت المخرجات وظهر التحيز. فجودة التمثيل تحدد عدالة الدقة.", evidence="تعريف بيانات التدريب وأثر التمثيل.", src="مراجعة الوحدة الأولى — نسخة الطالب (مقالي)"),
]
